#include "stdafx.h"#include "ServerExSharedPlugin_Honey.h"#include <ConnectH.h>#include <ConnectSM.h>#include <ConnectQB.h>#include <rsuNoNames.h>#include <MemoryServiceH5xx.h>#ifdef _MANAGED#pragma managed(push, off)#endifKNoName g_Objs, g_IOs, g_IOsObjsInfo, g_smIOs, g_qbIOs;static CBase* _StructFinder( LPCSTR ObjName, DWORD TypeID, int number ){  return g_Objs.FindStruct( ObjName, TypeID, number );}BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){	switch (ul_reason_for_call)	{	case DLL_PROCESS_ATTACH:    if( !pRegisterHWstructs )      LoadLibrary("HW5xxRegisterInRSU.dll");    if( pRegisterHWstructs )      pRegisterHWstructs();    if( !pRegisterSMstructs )      LoadLibrary("SM5xxRegisterInRSU.dll");    if( pRegisterSMstructs )      pRegisterSMstructs();    if( !pRegisterQBstructs )      LoadLibrary("QB5xxRegisterInRSU.dll");    if( pRegisterQBstructs )      pRegisterQBstructs();        g_Objs = KNoName::Create( "H5xx_Objs", false );    g_IOs = KNoName::Create( "H5xx_IOs", false );    g_IOsObjsInfo = KNoName::Create( "H5xx_Info", false );    KMemoryServiceH5xx::Instance().InitObjectsStructAllocator( NULL, NULL, _StructFinder );    g_smIOs = KNoName::Create( "SM5xx_IOs", false );    g_qbIOs = KNoName::Create( "QB5xx_IOs", false );    break;	case DLL_THREAD_ATTACH:	case DLL_THREAD_DETACH:	case DLL_PROCESS_DETACH:		break;	}    return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endif